// ignore_for_file: unused_element, unnecessary_cast

class AiFeatureStoreEntityTypeMonitoringConfigImportFeaturesAnalysis {
  /// Defines the baseline to do anomaly detection for feature values imported by each [entityTypes.importFeatureValues][] operation. The value must be one of the values below:
  /// * LATEST_STATS: Choose the later one statistics generated by either most recent snapshot analysis or previous import features analysis. If non of them exists, skip anomaly detection and only generate a statistics.
  /// * MOST_RECENT_SNAPSHOT_STATS: Use the statistics generated by the most recent snapshot analysis if exists.
  /// * PREVIOUS_IMPORT_FEATURES_STATS: Use the statistics generated by the previous import features analysis if exists.
  final String? anomalyDetectionBaseline;

  /// Whether to enable / disable / inherite default hebavior for import features analysis. The value must be one of the values below:
  /// * DEFAULT: The default behavior of whether to enable the monitoring. EntityType-level config: disabled.
  /// * ENABLED: Explicitly enables import features analysis. EntityType-level config: by default enables import features analysis for all Features under it.
  /// * DISABLED: Explicitly disables import features analysis. EntityType-level config: by default disables import features analysis for all Features under it.
  final String? state;

  AiFeatureStoreEntityTypeMonitoringConfigImportFeaturesAnalysis({
    this.anomalyDetectionBaseline,
    this.state,
  });

  Map<String, dynamic> toMap() {
    final map = <String, dynamic>{};
    final anomalyDetectionBaselineValue = anomalyDetectionBaseline;
    if (anomalyDetectionBaselineValue != null) {
      map['anomalyDetectionBaseline'] = anomalyDetectionBaselineValue;
    }
    final stateValue = state;
    if (stateValue != null) {
      map['state'] = stateValue;
    }
    return map;
  }

  factory AiFeatureStoreEntityTypeMonitoringConfigImportFeaturesAnalysis.fromMap(
      Map<String, dynamic> map) {
    return AiFeatureStoreEntityTypeMonitoringConfigImportFeaturesAnalysis(
      anomalyDetectionBaseline: map['anomalyDetectionBaseline'] == null
          ? null
          : map['anomalyDetectionBaseline'] as String,
      state: map['state'] == null ? null : map['state'] as String,
    );
  }
}
